from pathlib import Path


def load(path):
    return Path(path).read_text()


def save(path, text):
    Path(path).write_text(text)


def replace_once(path, old, new):
    text = load(path)
    if old not in text:
        raise SystemExit(f"anchor missing in {path}: {old[:120]!r}")
    save(path, text.replace(old, new, 1))

